#!/usr/bin/env python3
"""Retain the original notices for every locked browser runtime dependency."""
import argparse
import hashlib
import json
from pathlib import Path, PurePosixPath
import re


def render(root):
    dashboard = root / "dashboard"
    lock_bytes = (dashboard / "package-lock.json").read_bytes()
    lock = json.loads(lock_bytes)
    sections = ["StateSet Warehouse — browser runtime dependency notices\n"
                "Generated by scripts/dashboard_notices.py from package-lock.json and installed packages.\n"
                "Original third-party license and copyright texts follow; their terms remain unchanged.\n"
                "Includes all locked non-development packages, even if a bundler omits some code.\n"
                "Build tools, Rust crates and container packages are outside this browser notice file.\n"
                "Lockfile SHA256: " + hashlib.sha256(lock_bytes).hexdigest()]
    count = 0
    for name, entry in sorted(lock["packages"].items()):
        if not name or entry.get("dev") is True:
            continue
        parts = PurePosixPath(name).parts
        if ".." in parts or not name.startswith("node_modules/") or name.startswith("/"):
            raise ValueError("Invalid locked package path: " + name)
        package = dashboard / name
        package.resolve().relative_to((dashboard / "node_modules").resolve())
        manifest = json.loads((package / "package.json").read_text())
        if manifest["name"] != name.rsplit("node_modules/", 1)[-1] or manifest["version"] != entry["version"] or not entry.get("integrity"):
            raise ValueError("Installed/locked version or integrity mismatch: " + name)
        license_id = entry.get("license")
        if not license_id or license_id != manifest.get("license"):
            raise ValueError("Installed/locked license declaration requires review: " + name)
        notices = sorted(path for path in package.iterdir()
                         if path.is_file() and re.match(r"^(LICEN[CS]E|COPYING|NOTICE)([.\-_]|$)", path.name, re.I))
        if not notices:
            raise ValueError("Original license/notice text missing: " + name)
        sections.append("=" * 72 + "\n" + manifest["name"] + " " + entry["version"] + "\n"
                        "Declared license: " + license_id + "\nLocked package: " + name)
        for notice in notices:
            notice.resolve().relative_to(package.resolve())
            text = notice.read_text(encoding="utf8")
            if not text.strip():
                raise ValueError("Empty original notice: " + str(notice))
            sections.append("--- " + notice.name + " ---\n" + text.rstrip())
        count += 1
    if not count:
        raise ValueError("No runtime dependencies found; refusing an empty notice file")
    return "\n\n".join(sections) + "\n", count


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parent.parent)
    parser.add_argument("--check", action="store_true", help="Fail on absent/stale notices without writing")
    args = parser.parse_args()
    text, count = render(args.root.resolve())
    output = args.root / "dashboard/public/THIRD_PARTY_NOTICES.txt"
    if args.check:
        if not output.is_file() or output.read_bytes() != text.encode("utf8"):
            raise SystemExit("Browser notices are absent/stale; run python3 scripts/dashboard_notices.py after npm ci")
    else:
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_bytes(text.encode("utf8"))
    print("Verified original notices for %d locked browser runtime packages" % count)


if __name__ == "__main__":
    main()
